std::vector<Node*> open_list;
std::vector<Node*> closed_list;

open_list.push_back(graph.SNodes()[start_idx]);
graph.SNodes()[start_idx].g_value = 0.0;
graph.SNodes()[start_idx].h_value = calc_h_value(&graph.SNodes()[start_idx]);
graph.SNodes()[start_idx].parent = nullptr;

while (!open_list.empty()) {
    Node* current_node = next_node();
    open_list.erase(std::remove(open_list.begin(), open_list.end(), current_node), open_list.end());
    closed_list.push_back(current_node);

    if (current_node->index_ == end_idx) {
        return construct_final_path(current_node);
    }

    add_neighbors(current_node);
    for (Node* neighbor : current_node->neighbors) {
        if (std::find(closed_list.begin(), closed_list.end(), neighbor) != closed_list.end()) {
            continue;
        }

        float tentative_g_score = current_node->g_value + neighbor->distance(*current_node);
        if (std::find(open_list.begin(), open_list.end(), neighbor) == open_list.end()) {
            open_list.push_back(neighbor);
        } else if (tentative_g_score >= neighbor->g_value) {
            continue;
        }

        neighbor->parent = current_node;
        neighbor->g_value = tentative_g_score;
        neighbor->h_value = calc_h_value(neighbor);
    }
}

return path;

